-- All synthetic users, conversations, bookings, tickets and drafts roll back.
BEGIN;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
DO $test$
DECLARE client uuid:=gen_random_uuid(); other uuid:=gen_random_uuid(); staff uuid:=gen_random_uuid(); professional uuid:=gen_random_uuid(); who uuid;
 con uuid; run uuid; action uuid; booked uuid; request uuid:=gen_random_uuid(); sid uuid; day date:=(now() AT TIME ZONE 'Asia/Kathmandu')::date+4;
 slot timestamptz; result jsonb; failed boolean; payload jsonb; before_count bigint;
BEGIN
 IF has_function_privilege('anon','public.chatbud_assist(text,uuid,jsonb)','EXECUTE') OR has_function_privilege('authenticated','public.chatbud_assist(text,uuid,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'Browser can execute assistant gateway'; END IF;
 FOREACH who IN ARRAY ARRAY[client,other,staff,professional] LOOP
  INSERT INTO auth.users(id,email,email_confirmed_at) VALUES(who,'assistant-test-'||who||'@example.invalid',now());
  PERFORM public.chatbud_api('account',who,jsonb_build_object('email','assistant-test-'||who||'@example.invalid','name','Synthetic assistant test'));
 END LOOP;
 INSERT INTO core.role_assignment(user_id,role) VALUES(staff,'SUPPORT');
 INSERT INTO care.provider(id,public_slug,status) VALUES(professional,'assistant-test-'||professional,'APPROVED');
 INSERT INTO care.provider_scope(provider_id,profession_code,status,scope_description,policy_version,reviewed_by,approved_at)
 VALUES(professional,'dietitian','APPROVED','Synthetic test','test-v1',staff,now());
 INSERT INTO care.service(provider_id,profession_code,title,duration_minutes,price_minor,active) VALUES(professional,'dietitian','Synthetic nutrition session',45,150000,true) RETURNING id INTO sid;
 INSERT INTO care.availability_rule(provider_id,weekday,local_start,local_end,valid_from) VALUES(professional,extract(dow FROM day)::int,'09:00','12:00',day);
 SELECT starts_at INTO slot FROM care.open_slots(sid,day) LIMIT 1;
 IF slot IS NULL THEN RAISE EXCEPTION 'Fixture has no available slot'; END IF;
 con:=(public.chatbud_assist('create',client,'{"locale":"ne","consent":true}')->>'id')::uuid;
 failed:=false;
 BEGIN PERFORM public.chatbud_assist('conversation',other,jsonb_build_object('conversationId',con)); EXCEPTION WHEN insufficient_privilege THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Conversation crossed accounts'; END IF;
 failed:=false;
 BEGIN PERFORM public.chatbud_assist('team_overview',client); EXCEPTION WHEN insufficient_privilege THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Consumer read staff workspace'; END IF;
 run:=(public.chatbud_assist('begin_run',client,jsonb_build_object('conversationId',con,'requestId',request,'text','Please prepare the selected appointment.'))->>'id')::uuid;
 result:=public.chatbud_assist('begin_run',client,jsonb_build_object('conversationId',con,'requestId',request,'text','Please prepare the selected appointment.'));
 IF (result->>'id')::uuid<>run OR result->>'replay'<>'true' THEN RAISE EXCEPTION 'Run retry was not idempotent'; END IF;
 failed:=false;
 BEGIN PERFORM public.chatbud_assist('begin_run',client,jsonb_build_object('conversationId',con,'requestId',request,'text','A different request')); EXCEPTION WHEN raise_exception THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Request key accepted different text'; END IF;
 payload:=jsonb_build_object('serviceId',sid,'startsAt',slot);
 action:=(public.chatbud_assist('propose',client,jsonb_build_object('conversationId',con,'runId',run,'kind','BOOKING_REQUEST','payload',payload))->>'id')::uuid;
 IF EXISTS(SELECT 1 FROM care.appointment WHERE client_id=client) THEN RAISE EXCEPTION 'Proposing booked without confirmation'; END IF;
 failed:=false;
 BEGIN PERFORM public.chatbud_assist('decision',client,jsonb_build_object('actionId',action,'decision','confirm')); EXCEPTION WHEN raise_exception THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Incomplete response was confirmed'; END IF;
 PERFORM public.chatbud_assist('finish_run',client,jsonb_build_object('conversationId',con,'runId',run,'response',jsonb_build_object('text','Please review your pending request.','tokens',15)));
 failed:=false;
 BEGIN PERFORM public.chatbud_assist('decision',other,jsonb_build_object('actionId',action,'decision','confirm')); EXCEPTION WHEN insufficient_privilege THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Action crossed accounts'; END IF;
 UPDATE care.service SET price_minor=price_minor+100 WHERE id=sid;
 failed:=false;
 BEGIN PERFORM public.chatbud_assist('decision',client,jsonb_build_object('actionId',action,'decision','confirm')); EXCEPTION WHEN raise_exception THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Changed price accepted without fresh approval'; END IF;
 UPDATE care.service SET price_minor=price_minor-100 WHERE id=sid;
 result:=public.chatbud_assist('decision',client,jsonb_build_object('actionId',action,'decision','confirm'));
 booked:=(result->'result'->>'id')::uuid;
 IF NOT EXISTS(SELECT 1 FROM care.appointment WHERE id=booked AND client_id=client AND status='HELD') THEN RAISE EXCEPTION 'Confirmed action did not create pending request'; END IF;
 PERFORM public.chatbud_assist('decision',client,jsonb_build_object('actionId',action,'decision','confirm'));
 IF (SELECT count(*) FROM care.appointment WHERE client_id=client)<>1 THEN RAISE EXCEPTION 'Confirm retry duplicated booking'; END IF;
 result:=public.chatbud_assist('context',other);
 IF jsonb_array_length(result->'appointments')<>0 THEN RAISE EXCEPTION 'Tracking crossed accounts'; END IF;
 result:=public.chatbud_assist('context',professional);
 IF jsonb_array_length(result->'appointments')<>1 THEN RAISE EXCEPTION 'Professional cannot track their own appointments'; END IF;
 IF (result->'appointments'->0) ? 'clinicalNotes' OR (result->'appointments'->0) ? 'meetingUrl' THEN RAISE EXCEPTION 'Unnecessary clinical or meeting data exposed'; END IF;
 run:=(public.chatbud_assist('begin_run',client,jsonb_build_object('conversationId',con,'requestId',gen_random_uuid(),'text','Prepare a draft.'))->>'id')::uuid;
 failed:=false;
 BEGIN PERFORM public.chatbud_assist('propose',client,jsonb_build_object('conversationId',con,'runId',run,'kind','LEAD_RESEARCH','payload','{"query":"Public businesses in Nepal","platform":"public_web"}'::jsonb)); EXCEPTION WHEN insufficient_privilege THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Client prepared staff research action'; END IF;
 action:=(public.chatbud_assist('propose',client,jsonb_build_object('conversationId',con,'runId',run,'kind','MESSAGE_DRAFT','payload',jsonb_build_object('audience','professional','appointmentId',booked,'body','Synthetic message to my own professional.')))->>'id')::uuid;
 PERFORM public.chatbud_assist('finish_run',client,jsonb_build_object('conversationId',con,'runId',run,'response',jsonb_build_object('text','Review this draft.','tokens',10)));
 SELECT count(*) INTO before_count FROM ops.outbox_event;
 result:=public.chatbud_assist('decision',client,jsonb_build_object('actionId',action,'decision','confirm'));
 IF result->'result'->>'delivery'<>'NOT_SENT' OR (SELECT count(*) FROM ops.outbox_event)<>before_count THEN RAISE EXCEPTION 'Draft confirmation delivered a message'; END IF;
 IF NOT EXISTS(SELECT 1 FROM assist.communication_draft WHERE action_id=action AND recipient_id=professional AND created_by=client) THEN RAISE EXCEPTION 'Draft recipient mismatch'; END IF;
 run:=(public.chatbud_assist('begin_run',client,jsonb_build_object('conversationId',con,'requestId',gen_random_uuid(),'text','I want human support.'))->>'id')::uuid;
 action:=(public.chatbud_assist('propose',client,jsonb_build_object('conversationId',con,'runId',run,'kind','REQUEST_HUMAN','payload','{"summary":"Synthetic request for a human support handoff."}'::jsonb))->>'id')::uuid;
 PERFORM public.chatbud_assist('finish_run',client,jsonb_build_object('conversationId',con,'runId',run,'response',jsonb_build_object('text','Confirm the support request.','tokens',10)));
 result:=public.chatbud_assist('decision',client,jsonb_build_object('actionId',action,'decision','confirm'));
 IF NOT EXISTS(SELECT 1 FROM assist.conversation WHERE id=con AND status='HUMAN_REQUESTED' AND ticket_id=(result->'result'->>'id')::uuid) THEN RAISE EXCEPTION 'Handoff ticket not linked'; END IF;
 failed:=false;
 BEGIN PERFORM public.chatbud_assist('begin_run',client,jsonb_build_object('conversationId',con,'requestId',gen_random_uuid(),'text','Continue AI anyway')); EXCEPTION WHEN raise_exception THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'AI continued during human handoff'; END IF;
 con:=(public.chatbud_assist('create',staff,'{"locale":"hi","consent":true}')->>'id')::uuid;
 run:=(public.chatbud_assist('begin_run',staff,jsonb_build_object('conversationId',con,'requestId',gen_random_uuid(),'text','Prepare business research.'))->>'id')::uuid;
 action:=(public.chatbud_assist('propose',staff,jsonb_build_object('conversationId',con,'runId',run,'kind','LEAD_RESEARCH','payload','{"query":"Public wellness businesses for partnerships","platform":"public_web"}'::jsonb))->>'id')::uuid;
 PERFORM public.chatbud_assist('finish_run',staff,jsonb_build_object('conversationId',con,'runId',run,'response',jsonb_build_object('text','Review the research brief.','tokens',10)));
 result:=public.chatbud_assist('decision',staff,jsonb_build_object('actionId',action,'decision','confirm'));
 IF result->'result'->>'status'<>'WAITING_CONNECTOR' THEN RAISE EXCEPTION 'Unconnected search claimed to run'; END IF;
 UPDATE core.app_user SET status='SUSPENDED' WHERE id=other;
 failed:=false;
 BEGIN PERFORM public.chatbud_assist('context',other); EXCEPTION WHEN insufficient_privilege THEN failed:=true; END;
 IF NOT failed THEN RAISE EXCEPTION 'Suspended account retained AI access'; END IF;
END $test$;
ROLLBACK;
SELECT 'PASS: AI ownership, roles, idempotency, confirmation, booking, tracking, drafts, human handoff, research gating and suspension; all fixtures rolled back.' AS result;
